import Foundation

/// Every Lifestream event, with its closed sets, uniqueness and cohort flag compiled in. Generated by `midgar gen --write` from registry/signals.yaml. Edit the registry, not this file.
public enum MidgarSignal: Sendable, Equatable {
    /// Cold launches of an app. Reserved: No MidgarKit or app code records it yet; it stays accepted so the worker's event set does not shrink.
    case appLaunch
    /// Daily, weekly and monthly active installs.
    case appActive(period: Period)
    /// Installs that finished first-run onboarding. Reserved: Helia marks onboarding complete but only logs it; no code sends the event yet.
    case onboardingComplete
    /// How often a paywall is seen, and from where.
    case paywallView(placement: Placement)
    /// Purchases completed in the app, by product.
    case paywallPurchase(product: String)
    /// How a started checkout ended, by product, so the drop-off after the paywall is countable.
    case paywallCheckout(outcome: Outcome, product: String)
    /// First-run steps before a purchase.
    case funnelStep(step: FunnelStep)
    /// The cross-promo portal opened, and from which placement.
    case portalOpen(storefront: Storefront? = nil, placement: Placement)
    /// A promoted app shown in the cross-promo portal.
    case impression(appId: String, storefront: Storefront? = nil, placement: Placement)
    /// A promoted app tapped in the cross-promo portal.
    case tap(appId: String, storefront: Storefront? = nil, placement: Placement)
    /// A promoted app's store page loaded from the cross-promo portal.
    case loaded(appId: String, storefront: Storefront? = nil, placement: Placement)
    /// A promoted app opened from the cross-promo portal.
    case launch(appId: String, storefront: Storefront? = nil, placement: Placement)
    /// The App Store overlay for a promoted app presented by Midgar.moment.
    case overlay(appId: String, storefront: Storefront? = nil, placement: Placement)
    /// Daily MetricKit performance numbers of an install, for release health.
    case metricsDaily(coldLaunchMs: Double? = nil, hangSecondsPerHour: Double? = nil, foregroundSeconds: Double? = nil, peakMemoryMB: Double? = nil)
    /// Crash, hang, disk-write and CPU-exception counts from MetricKit diagnostics.
    case metricsDiagnostics(crashes: Int? = nil, hangs: Int? = nil, diskWrites: Int? = nil, cpuExceptions: Int? = nil)

    /// How often one install may send an event.
    public enum Uniqueness: String, Sendable, CaseIterable {
        case each = "each"
        case daily = "daily"
        case weekly = "weekly"
        case monthly = "monthly"
        case lifetime = "lifetime"
        case perPeriod = "per-period"
    }

    /// The closed set Period; the worker stores any other value as `other`.
    public enum Period: String, Sendable, CaseIterable {
        case day, week, month
    }

    /// The closed set Placement; the worker stores any other value as `other`.
    public enum Placement: String, Sendable, CaseIterable {
        case settings, entry, onboarding, launch, paywall, feature, limit
    }

    /// The closed set Outcome; the worker stores any other value as `other`.
    public enum Outcome: String, Sendable, CaseIterable {
        case started, purchased, pending, cancelled, failed
    }

    /// The closed set FunnelStep; the worker stores any other value as `other`.
    public enum FunnelStep: String, Sendable, CaseIterable {
        case samplePlayed = "sample_played", addMusicOpened = "add_music_opened", libraryFilled = "library_filled", importSucceeded = "import_succeeded", importFailed = "import_failed", trialStarted = "trial_started"
    }

    /// The closed set Storefront; the worker stores any other value as `other`.
    public enum Storefront: String, Sendable, CaseIterable {
        case ad, ae, af, ag, ai, al, am, ao, aq, ar, `as`, at
        case au, aw, ax, az, ba, bb, bd, be, bf, bg, bh, bi
        case bj, bl, bm, bn, bo, bq, br, bs, bt, bv, bw, by
        case bz, ca, cc, cd, cf, cg, ch, ci, ck, cl, cm, cn
        case co, cr, cu, cv, cw, cx, cy, cz, de, dj, dk, dm
        case `do`, dz, ec, ee, eg, eh, er, es, et, fi, fj, fk
        case fm, fo, fr, ga, gb, gd, ge, gf, gg, gh, gi, gl
        case gm, gn, gp, gq, gr, gs, gt, gu, gw, gy, hk, hm
        case hn, hr, ht, hu, id, ie, il, im, `in`, io, iq, ir
        case `is`, it, je, jm, jo, jp, ke, kg, kh, ki, km, kn
        case kp, kr, kw, ky, kz, la, lb, lc, li, lk, lr, ls
        case lt, lu, lv, ly, ma, mc, md, me, mf, mg, mh, mk
        case ml, mm, mn, mo, mp, mq, mr, ms, mt, mu, mv, mw
        case mx, my, mz, na, nc, ne, nf, ng, ni, nl, no, np
        case nr, nu, nz, om, pa, pe, pf, pg, ph, pk, pl, pm
        case pn, pr, ps, pt, pw, py, qa, re, ro, rs, ru, rw
        case sa, sb, sc, sd, se, sg, sh, si, sj, sk, sl, sm
        case sn, so, sr, ss, st, sv, sx, sy, sz, tc, td, tf
        case tg, th, tj, tk, tl, tm, tn, to, tr, tt, tv, tw
        case tz, ua, ug, um, us, uy, uz, va, vc, ve, vg, vi
        case vn, vu, wf, ws, ye, yt, za, zm, zw
    }

    /// The event name on the wire.
    public var name: String {
        switch self {
        case .appLaunch: return "app.launch"
        case .appActive: return "app.active"
        case .onboardingComplete: return "onboarding.complete"
        case .paywallView: return "paywall.view"
        case .paywallPurchase: return "paywall.purchase"
        case .paywallCheckout: return "paywall.checkout"
        case .funnelStep: return "funnel.step"
        case .portalOpen: return "portal_open"
        case .impression: return "impression"
        case .tap: return "tap"
        case .loaded: return "loaded"
        case .launch: return "launch"
        case .overlay: return "overlay"
        case .metricsDaily: return "metrics.daily"
        case .metricsDiagnostics: return "metrics.diagnostics"
        }
    }

    /// Every event name the registry declares.
    public static let allNames: [String] = ["app.launch", "app.active", "onboarding.complete", "paywall.view", "paywall.purchase", "paywall.checkout", "funnel.step", "portal_open", "impression", "tap", "loaded", "launch", "overlay", "metrics.daily", "metrics.diagnostics"]

    /// The props the event sends, without the cohort, which MidgarKit stamps.
    public var props: [String: MidgarSignalValue] {
        switch self {
        case .appLaunch: return [:]
        case .appActive(let period): return ["period": .string(period.rawValue)]
        case .onboardingComplete: return [:]
        case .paywallView(let placement): return ["placement": .string(placement.rawValue)]
        case .paywallPurchase(let product): return ["product": .string(product)]
        case .paywallCheckout(let outcome, let product): return ["outcome": .string(outcome.rawValue), "product": .string(product)]
        case .funnelStep(let step): return ["step": .string(step.rawValue)]
        case .portalOpen(let storefront, let placement):
            var props: [String: MidgarSignalValue] = ["placement": .string(placement.rawValue)]
            if let storefront { props["storefront"] = .string(storefront.rawValue) }
            return props
        case .impression(let appId, let storefront, let placement):
            var props: [String: MidgarSignalValue] = ["appId": .string(appId), "placement": .string(placement.rawValue)]
            if let storefront { props["storefront"] = .string(storefront.rawValue) }
            return props
        case .tap(let appId, let storefront, let placement):
            var props: [String: MidgarSignalValue] = ["appId": .string(appId), "placement": .string(placement.rawValue)]
            if let storefront { props["storefront"] = .string(storefront.rawValue) }
            return props
        case .loaded(let appId, let storefront, let placement):
            var props: [String: MidgarSignalValue] = ["appId": .string(appId), "placement": .string(placement.rawValue)]
            if let storefront { props["storefront"] = .string(storefront.rawValue) }
            return props
        case .launch(let appId, let storefront, let placement):
            var props: [String: MidgarSignalValue] = ["appId": .string(appId), "placement": .string(placement.rawValue)]
            if let storefront { props["storefront"] = .string(storefront.rawValue) }
            return props
        case .overlay(let appId, let storefront, let placement):
            var props: [String: MidgarSignalValue] = ["appId": .string(appId), "placement": .string(placement.rawValue)]
            if let storefront { props["storefront"] = .string(storefront.rawValue) }
            return props
        case .metricsDaily(let coldLaunchMs, let hangSecondsPerHour, let foregroundSeconds, let peakMemoryMB):
            var props: [String: MidgarSignalValue] = [:]
            if let coldLaunchMs { props["coldLaunchMs"] = .double(coldLaunchMs) }
            if let hangSecondsPerHour { props["hangSecondsPerHour"] = .double(hangSecondsPerHour) }
            if let foregroundSeconds { props["foregroundSeconds"] = .double(foregroundSeconds) }
            if let peakMemoryMB { props["peakMemoryMB"] = .double(peakMemoryMB) }
            return props
        case .metricsDiagnostics(let crashes, let hangs, let diskWrites, let cpuExceptions):
            var props: [String: MidgarSignalValue] = [:]
            if let crashes { props["crashes"] = .int(crashes) }
            if let hangs { props["hangs"] = .int(hangs) }
            if let diskWrites { props["diskWrites"] = .int(diskWrites) }
            if let cpuExceptions { props["cpuExceptions"] = .int(cpuExceptions) }
            return props
        }
    }

    /// How often one install may send this event.
    public var uniqueness: Uniqueness {
        switch self {
        case .appLaunch: return .each
        case .appActive: return .perPeriod
        case .onboardingComplete: return .each
        case .paywallView: return .each
        case .paywallPurchase: return .each
        case .paywallCheckout: return .each
        case .funnelStep: return .lifetime
        case .portalOpen: return .each
        case .impression: return .each
        case .tap: return .each
        case .loaded: return .each
        case .launch: return .each
        case .overlay: return .each
        case .metricsDaily: return .each
        case .metricsDiagnostics: return .each
        }
    }

    /// Whether MidgarKit stamps the install week on this event.
    public var carriesCohort: Bool {
        switch self {
        case .appActive, .funnelStep: return true
        default: return false
        }
    }
}
